#!/usr/bin/env node

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const rootDir = process.cwd();
const sourcePath = resolve(rootDir, "AGENTS.md");
const isCheckMode = process.argv.includes("--check");

const SOURCE_HEADER =
  "<!-- AUTO-GENERATED FROM `AGENTS.md` (canonical source). DO NOT EDIT THIS FILE DIRECTLY. Use `bun run guidelines:sync`. -->\n\n";

const mirrorTargets = [
  {
    path: ".agent/rules/guidelines.md",
    prefix: "---\ntrigger: always_on\n---\n\n" + SOURCE_HEADER,
  },
  {
    path: ".junie/guidelines.md",
    prefix: "---\ntrigger: always_on\n---\n\n" + SOURCE_HEADER,
  },
  {
    path: "CLAUDE.md",
    prefix: SOURCE_HEADER,
  },
];

const canonical = normalize(readFileSync(sourcePath, "utf8"));
const diffs = [];

for (const target of mirrorTargets) {
  const absoluteTargetPath = resolve(rootDir, target.path);
  const expectedContent = normalize(target.prefix + canonical);
  const actualContent = readIfExists(absoluteTargetPath);

  if (actualContent !== expectedContent) {
    diffs.push(target.path);
    if (!isCheckMode) {
      mkdirSync(dirname(absoluteTargetPath), { recursive: true });
      writeFileSync(absoluteTargetPath, expectedContent, "utf8");
      console.log(`updated: ${target.path}`);
    }
  } else if (!isCheckMode) {
    console.log(`unchanged: ${target.path}`);
  }
}

if (isCheckMode && diffs.length > 0) {
  console.error("Guideline mirrors are out of sync:");
  for (const path of diffs) {
    console.error(`- ${path}`);
  }
  console.error("Run `bun run guidelines:sync` and commit updated files.");
  process.exit(1);
}

if (!isCheckMode) {
  console.log("Guidelines sync complete.");
}

function normalize(content) {
  const withoutBom = content.replace(/^\uFEFF/, "");
  return withoutBom.replace(/\r\n/g, "\n").trimEnd() + "\n";
}

function readIfExists(path) {
  try {
    return normalize(readFileSync(path, "utf8"));
  } catch {
    return "";
  }
}
